p("REQUIRED — Time rate of change of flux, ΔΦ/Δt = ?","مطلوب — فلوکس کی تبدیلی کی شرحِ وقت، ΔΦ/Δt = ؟","غوښتل شوی — د فلوکس د بدلون کچه، ΔΦ/Δt = ؟"),
